"""Self-contained, static operations report generated from executed scenarios."""

from html import escape
import json
from typing import Any


def render_report(report: dict[str, Any]) -> str:
    state = report["ledger"]
    bench = report["benchmark"]
    reconciliation = report["reconciliation"]
    events = state["events"]
    posted = sum(event["status"] == "posted" for event in events)
    def badge(value: str) -> str:
        return f'<span class="badge {escape(value)}">{escape(value.replace("_", " "))}</span>'
    cases = "".join(f'<article class="case"><span class="case-number">{i:02}</span><div><h3>{escape(case["name"])}</h3><p>{escape(case["detail"])}</p></div><span class="check" aria-label="passed">✓</span></article>' for i, case in enumerate(report["checks"], 1))
    balance_rows = "".join(f'<tr><td><strong>{r["currency"]}</strong></td><td>{r["debit_cents"]:,}</td><td>{r["credit_cents"]:,}</td><td><span class="zero">{r["difference_cents"]:,}</span></td></tr>' for r in state["balance"])
    event_rows = "".join(f'<tr data-status="{escape(r["status"])}"><td><button class="event-link" data-event="{escape(r["event_id"])}"><code>{escape(r["event_id"])}</code><span aria-hidden="true"> ↗</span></button><small>{escape(r["payment_id"])}</small></td><td>{escape(r["kind"].split(".")[1])}</td><td>{escape(r["currency"])} {r["amount_cents"] / 100:,.2f}</td><td>{badge(r["status"])}<small>{escape(r["reason"] or "")}</small></td></tr>' for r in events)
    recon_rows = "".join(f'<tr data-category="{escape(r["category"])}"><td><code>{escape(r["event_id"])}</code></td><td>{badge(r["category"])}</td><td>{escape(str(r["expected"]["amount_cents"]) + " " + r["expected"]["currency"] if r["expected"] else "—")}</td><td>{escape(" / ".join(str(p["amount_cents"]) + " " + p["currency"] for p in r["provider_rows"]) or "—")}</td></tr>' for r in reconciliation["results"])
    counts = "".join(f'<button class="recon-count" data-category="{escape(category)}" aria-pressed="false"><b>{count}</b><span>{escape(category.replace("_", " "))}</span></button>' for category, count in reconciliation["counts"].items())
    provenance = escape(" · ".join(f'{key}: {value}' for key, value in bench["environment"].items()))
    embedded = json.dumps({"events": events, "journals": state["journals"], "lines": state["journal_lines"]}, separators=(",", ":")).replace("<", "\\u003c")
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Executed failure scenarios, ledger invariants and settlement reconciliation from the Clearinghouse payment ledger."><title>Clearinghouse — Operations evidence</title>
<style>
:root{{--ink:#172b36;--muted:#60717a;--line:#dbe3e2;--paper:#f5f7f3;--green:#137861;--navy:#102c35;--amber:#9c650d;--red:#a84636}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}a{{color:inherit}}header{{background:var(--navy);color:white;padding:30px max(5vw,24px) 54px}}.topline{{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #34525b;padding-bottom:22px;margin-bottom:40px}}.brand{{font-size:19px;font-weight:750;letter-spacing:-.5px}}.brand span{{color:#89d6b8;margin-right:10px}}.tag{{font-size:11px;text-transform:uppercase;letter-spacing:1.6px;color:#b9d7d5}}h1{{font-size:clamp(35px,5.2vw,62px);line-height:1.08;letter-spacing:-2.3px;margin:13px 0 20px;max-width:780px}}header p{{color:#bcd0d0;font-size:17px;max-width:720px;margin:0}}main{{max-width:1240px;margin:auto;padding:0 24px 60px}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:-25px}}.metric{{background:white;border:1px solid var(--line);border-radius:10px;padding:24px}}.metric strong{{font-size:35px;line-height:1;display:block;letter-spacing:-1px}}.metric span{{display:block;font-size:12px;color:var(--muted);margin-top:12px}}.metric strong.accent{{color:var(--green)}}section{{margin-top:42px}}.section-title{{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:17px}}h2{{font-size:23px;letter-spacing:-.6px;margin:0}}.eyebrow{{color:var(--green);text-transform:uppercase;letter-spacing:1.7px;font-size:10px;font-weight:800;display:block;margin-bottom:7px}}.note{{color:var(--muted);font-size:12px}}.columns{{display:grid;grid-template-columns:1.25fr 1fr;gap:24px}}.panel{{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden}}.case{{display:flex;align-items:start;gap:15px;padding:19px 22px;border-bottom:1px solid #edf0ed}}.case:last-child{{border:0}}.case-number{{font:12px ui-monospace,monospace;color:#82958f;padding-top:3px}}.case h3{{font-size:14px;margin:0 0 4px}}.case p{{margin:0;color:var(--muted);font-size:12px;max-width:440px}}.check{{margin-left:auto;color:var(--green);font-size:17px;font-weight:700}}.panel-head{{padding:20px 22px;border-bottom:1px solid var(--line)}}.panel-head h3{{margin:0;font-size:15px}}.panel-head p{{font-size:12px;color:var(--muted);margin:5px 0 0}}table{{border-collapse:collapse;width:100%;text-align:left;font-size:12px}}th{{font-size:10px;letter-spacing:.7px;color:var(--muted);font-weight:600;text-transform:uppercase;background:#fbfcfa}}td,th{{padding:14px 18px;border-bottom:1px solid #edf0ed}}tr:last-child td{{border:0}}td small{{display:block;color:var(--muted);font-size:10px;margin-top:3px}}code{{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px}}.zero{{color:var(--green);font-weight:800}}.badge{{display:inline-block;padding:3px 8px;background:#edf2ee;border-radius:5px;font-size:10px;font-weight:700;white-space:nowrap}}.posted,.exact{{background:#e3f3e9;color:#176144}}.pending,.missing,.duplicate,.amount_mismatch,.currency_mismatch{{background:#fff0d6;color:#865b13}}.rejected,.unexpected{{background:#fce9e5;color:#923f32}}.context{{margin:0;padding:18px 22px;font-size:12px;color:var(--muted)}}.mini-metrics{{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--line)}}.mini-metrics div{{padding:20px 12px;text-align:center;border-right:1px solid var(--line)}}.mini-metrics div:last-child{{border:0}}.mini-metrics b{{display:block;font-size:22px;letter-spacing:-.5px}}.mini-metrics span{{font-size:10px;color:var(--muted)}}.recon-counts{{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:15px}}.recon-count{{padding:16px;background:#eaf0eb;border:1px solid #dde6de;border-radius:7px}}.recon-count b{{display:block;font-size:23px}}.recon-count span{{display:block;font-size:10px;color:var(--muted)}}.scroll{{overflow-x:auto}}.filters{{display:flex;gap:7px;flex-wrap:wrap}}button{{border:1px solid var(--line);background:white;color:var(--muted);padding:7px 12px;border-radius:6px;font-size:11px;cursor:pointer}}button[aria-pressed="true"]{{background:var(--navy);color:white;border-color:var(--navy)}}button:focus-visible{{outline:3px solid #74bdb0;outline-offset:2px}}.architecture{{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:22px}}.architecture span{{background:#edf3ef;border-radius:5px;padding:9px 12px;font-size:11px;font-weight:650}}.architecture em{{font-style:normal;color:#7b9189}}footer{{border-top:1px solid var(--line);margin-top:42px;padding-top:20px;font-size:11px;color:var(--muted);display:flex;justify-content:space-between;gap:25px}}[hidden]{{display:none!important}}@media(max-width:800px){{.columns{{grid-template-columns:1fr}}.metrics{{grid-template-columns:repeat(2,1fr)}}.recon-counts{{grid-template-columns:repeat(3,1fr)}}header{{padding-bottom:45px}}.tag{{font-size:9px}}.section-title{{align-items:start;flex-direction:column;gap:12px}}footer{{flex-direction:column}}}}@media(prefers-reduced-motion:no-preference){{button{{transition:background .15s}}}}
.event-link{{padding:0;border:0;color:var(--green);background:transparent;text-align:left}}.event-link:hover{{text-decoration:underline}}.recon-count{{text-align:left;color:var(--ink)}}.recon-count[aria-pressed="true"] span{{color:#cfe2df}}.table-tools{{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 18px;border-bottom:1px solid var(--line)}}input[type="search"]{{font:12px system-ui;width:min(300px,100%);padding:9px 12px;border:1px solid var(--line);border-radius:6px;background:#fbfcfa;color:var(--ink)}}input:focus-visible{{outline:3px solid #74bdb0;outline-offset:1px}}dialog{{position:fixed;inset:0 0 0 auto;width:min(530px,100%);max-width:100%;height:100%;max-height:100%;margin:0;border:0;border-left:1px solid var(--line);padding:0;background:var(--paper);color:var(--ink);box-shadow:-15px 0 70px #102c352b}}dialog::backdrop{{background:#102c3577}}.drawer-top{{display:flex;align-items:center;justify-content:space-between;padding:22px 26px;background:var(--navy);color:white}}.drawer-top .eyebrow{{color:#b2dccc;margin:0}}.drawer-body{{padding:26px}}.drawer-body h2{{font-size:25px;overflow-wrap:anywhere}}.drawer-body p{{color:var(--muted);font-size:13px}}.drawer-body dl{{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:26px 0}}dt{{font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--muted)}}dd{{margin:4px 0 0;font-size:14px;font-weight:600;overflow-wrap:anywhere}}.drawer-journal{{margin-top:20px}}.drawer-journal h3{{font-size:14px;margin:0 0 7px}}.drawer-journal code{{font-size:10px;display:block;overflow-wrap:anywhere;color:var(--muted);margin-bottom:10px}}.drawer-empty{{padding:20px;border:1px dashed #b9c9c2;border-radius:8px;font-size:13px;color:var(--muted)}}
</style></head><body>
<header><div class="topline"><div class="brand"><span>▦</span>Clearinghouse</div><div class="tag">Payment infrastructure / evidence report</div></div><span class="tag">Durability is a behavior you can test</span><h1>Every payment accounted for.<br>Even when delivery fails.</h1><p>An executed tour of a durable event ledger: replayed webhooks, process crashes, leased delivery, and settlement discrepancies. Synthetic data. Real database transactions.</p></header>
<main><div class="metrics"><div class="metric"><strong>{posted}</strong><span>Provider events posted</span></div><div class="metric"><strong class="accent">{len(report["checks"])}/{len(report["checks"])}</strong><span>Failure &amp; invariant scenarios passed</span></div><div class="metric"><strong class="accent">0¢</strong><span>Unbalanced journal difference</span></div><div class="metric"><strong>{report["consumer_receipts"]}</strong><span>Unique downstream receipts</span></div></div>
<section><div class="section-title"><div><span class="eyebrow">01 / Failure laboratory</span><h2>Recoveries with evidence</h2></div><span class="note">Executed by <code>python -m clearinghouse demo</code></span></div><div class="columns"><div class="panel">{cases}</div><div><div class="panel"><div class="panel-head"><h3>Trial balance, by currency</h3><p>Posted journals include accounting reversals. All values below are integer cents.</p></div><div class="scroll"><table><thead><tr><th>Currency</th><th>Debits</th><th>Credits</th><th>Difference</th></tr></thead><tbody>{balance_rows}</tbody></table></div><p class="context">Each journal is sealed only after a database trigger verifies balance. Posted headers and lines reject updates, deletes, and appended entries.</p></div><div class="panel" style="margin-top:20px"><div class="panel-head"><h3>Measured local commit cost</h3><p>{bench["operations"]} sequential captures · SQLite WAL · synchronous=FULL</p></div><div class="mini-metrics"><div><b>{bench["p50_ms"]:.2f}</b><span>p50 milliseconds</span></div><div><b>{bench["p95_ms"]:.2f}</b><span>p95 milliseconds</span></div><div><b>{bench["operations_per_second"]:.0f}</b><span>operations / second</span></div></div><p class="context">A small local measurement, not a throughput guarantee. No HTTP, delivery, or network storage. {provenance}.</p></div></div></div></section>
<section><div class="section-title"><div><span class="eyebrow">02 / Settlement control</span><h2>Explain every discrepancy</h2></div><div><span class="note">{reconciliation["provider_row_count"]} provider rows · {reconciliation["expected_event_count"]} expected events</span> <button data-category="all" aria-pressed="true">Show all</button></div></div><div class="recon-counts">{counts}</div><div class="panel scroll"><table id="settlements"><thead><tr><th>Provider event</th><th>Result</th><th>Expected cents</th><th>Observed cents</th></tr></thead><tbody>{recon_rows}</tbody></table></div><p class="note">Duplicate settlement IDs or event rows take precedence over matching amounts. Refunds are negative; currencies are compared before amounts. Reconciliation reports differences and never edits the ledger.</p></section>
<section><div class="section-title"><div><span class="eyebrow">03 / Event explorer</span><h2>Trace the business outcome</h2></div><div class="filters" role="group" aria-label="Filter events by status"><button data-filter="all" aria-pressed="true">All events</button><button data-filter="posted" aria-pressed="false">Posted</button><button data-filter="pending" aria-pressed="false">Pending</button><button data-filter="rejected" aria-pressed="false">Rejected</button></div></div><div class="panel scroll"><div class="table-tools"><input type="search" id="event-search" aria-label="Search events and payments" placeholder="Search an event or payment…"><span id="event-count" class="note" aria-live="polite">{len(events)} events</span></div><table id="events"><thead><tr><th>Event / payment</th><th>Kind</th><th>Amount</th><th>Status</th></tr></thead><tbody>{event_rows}</tbody></table></div><p class="note">Provider event state and accounting state are separate: correcting a journal does not refund a payment or change the provider settlement expectation.</p></section>
<section><div class="section-title"><div><span class="eyebrow">04 / Transaction boundary</span><h2>One local commit, then retryable delivery</h2></div></div><div class="panel"><div class="architecture"><span>Strict JSON event</span><em>→</em><span>Idempotency check</span><em>→</em><span>Event + journal + outbox</span><em>→</em><span>Leased worker</span><em>→</em><span>Consumer inbox</span></div><p class="context">The event, balanced journal, idempotency response, and outbox message share one SQLite transaction. Delivery is at least once; a consumer receipt transaction makes retries safe for the demonstrated side effect. SQLite has one writer. This is a single-host reference implementation.</p></div></section>
<footer><span>Clearinghouse · Bowen Zhu · {escape(report["generated_at"])}<br>Generated from an executable synthetic demo. This page is a static evidence report, not a live payment service.</span><span>No production traffic, real card data, or external provider integration.<br>Run the repository demo to regenerate every number.</span></footer></main>
<dialog id="journal-drawer" aria-labelledby="drawer-title"><div class="drawer-top"><span class="eyebrow">Transaction inspector</span><button id="close-drawer" aria-label="Close transaction inspector">Close ×</button></div><div class="drawer-body"><h2 id="drawer-title"></h2><p id="drawer-description"></p><dl id="drawer-fields"></dl><div id="drawer-journals"></div></div></dialog>
<script id="evidence-data" type="application/json">{embedded}</script>
<script>
const evidence=JSON.parse(document.getElementById('evidence-data').textContent);
let currentStatus='all';
function filterEvents(){{const query=document.getElementById('event-search').value.toLowerCase();let shown=0;document.querySelectorAll('#events tbody tr').forEach(row=>{{row.hidden=!(currentStatus==='all'||row.dataset.status===currentStatus)||!row.textContent.toLowerCase().includes(query);if(!row.hidden)shown++;}});document.getElementById('event-count').textContent=shown+' events';}}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{{currentStatus=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filterEvents();}}));
document.getElementById('event-search').addEventListener('input',filterEvents);
document.querySelectorAll('button[data-category]').forEach(button=>button.addEventListener('click',()=>{{const category=button.dataset.category;document.querySelectorAll('button[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('#settlements tbody tr').forEach(row=>row.hidden=category!=='all'&&row.dataset.category!==category);}}));
const drawer=document.getElementById('journal-drawer');
document.getElementById('close-drawer').addEventListener('click',()=>drawer.close());
function element(tag,text,className){{const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;return node;}}
document.querySelectorAll('[data-event]').forEach(button=>button.addEventListener('click',()=>{{const event=evidence.events.find(e=>e.event_id===button.dataset.event);document.getElementById('drawer-title').textContent=event.event_id;document.getElementById('drawer-description').textContent='Provider event → immutable accounting evidence';const fields=document.getElementById('drawer-fields');fields.replaceChildren();[['Payment',event.payment_id],['Status',event.status],['Amount',event.currency+' '+(event.amount_cents/100).toFixed(2)],['Type',event.kind],['Occurred',event.occurred_at],['Reason',event.reason||'Accepted provider event']].forEach(([label,value])=>{{const group=document.createElement('div');group.append(element('dt',label),element('dd',value));fields.append(group);}});const target=document.getElementById('drawer-journals');target.replaceChildren();const original=evidence.journals.find(j=>j.event_id===event.event_id);if(!original){{target.append(element('p',event.status==='pending'?'No journal yet. This refund is waiting for its capture dependency.':'No journal was posted. The event was rejected without changing accounting balances.','drawer-empty'));}}else{{const journals=[original,...evidence.journals.filter(j=>j.reversal_of===original.journal_id)];journals.forEach(journal=>{{const section=element('section','', 'drawer-journal');section.append(element('h3',journal.reversal_of?'Accounting reversal':'Original journal'),element('code',journal.journal_id));const table=document.createElement('table');const head=document.createElement('thead');const header=document.createElement('tr');['Account','Debit ¢','Credit ¢'].forEach(label=>header.append(element('th',label)));head.append(header);table.append(head);const body=document.createElement('tbody');evidence.lines.filter(line=>line.journal_id===journal.journal_id).forEach(line=>{{const row=document.createElement('tr');[line.account,line.debit_cents.toLocaleString(),line.credit_cents.toLocaleString()].forEach(value=>row.append(element('td',value)));body.append(row);}});table.append(body);section.append(table,element('p',journal.reason));target.append(section);}});}}drawer.showModal();}}));
</script></body></html>'''
